function report({ state, workflow, now, chatId }) {
  const items = state.items,
    workflowName = workflow.name;
  if (
    !Array.isArray(items) ||
    typeof workflowName !== "string" ||
    !workflowName.trim() ||
    workflowName.startsWith("YOUR_") ||
    typeof chatId !== "string" ||
    !chatId.trim() ||
    chatId.startsWith("YOUR_")
  )
    throw Error("Set the workflow name and Telegram chat");
  const t = Date.parse(now);
  if (!Number.isFinite(t)) throw Error("Invalid report time");
  const lines = [];
  for (const e of items) {
    if (
      !["canceled", "crashed", "error", "new", "running", "success", "unknown", "waiting"].includes(
        e.status,
      ) ||
      typeof e.startedAt !== "string" ||
      !Number.isFinite(Date.parse(e.startedAt)) ||
      e.id === undefined ||
      e.id === null
    )
      throw Error("Invalid execution");
    if (
      ["error", "crashed"].includes(e.status) &&
      Date.parse(e.startedAt) > t - 604800000 &&
      Date.parse(e.startedAt) <= t
    )
      lines.push(`⚠️ Workflow ${workflowName} failed. Execution ${e.id}; started ${e.startedAt}`);
  }
  const text = lines.join("\n");
  if (text.length > 4096) throw Error("Report exceeds the Telegram message limit");
  return {
    send: lines.length > 0,
    text: text || "No unfinished executions",
    chatId,
    count: lines.length,
  };
}

const x = report({
  state: { items: $input.all().map((x) => x.json) },
  workflow: { name: "YOUR_N8N_WORKFLOW_NAME" },
  now: new Date().toISOString(),
  chatId: "YOUR_TELEGRAM_CHAT_ID",
});
return x.send ? [{ json: x }] : [];
